import{_ as A,h as l,i as e,c as o,v as t,p as n,x as r,m as R,e as s,S as P}from"./chunks/framework.Dvtg8yj2.js";const m=JSON.parse('{"title":"RLAIF","description":"","frontmatter":{"title":"RLAIF","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rlaif.md","filePath":"llm/rlaif.md","lastUpdated":1788454257000}'),L={name:"llm/rlaif.md"};function I(p,a,d,F,c,h){const i=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="rlaif" tabindex="-1">RLAIF <a class="header-anchor" href="#rlaif" aria-label="Permalink to &quot;RLAIF&quot;">​</a></h1><div class="epigraph"><p>用大语言模型按原则给成对回答打偏好，再像 RLHF 那样训奖励、做强化学习；在摘要与对话上，AI 反馈可以达到与人类反馈相近的胜率，而标注成本低一个数量级。</p><footer>—— Lee et al., RLAIF vs. RLHF: Scaling Reinforcement Learning from Human Feedback with AI Feedback, 2023</footer></div><p>Lee、Phatale、Mansoor 等人（Google）的 RLAIF 把 Constitutional AI 里「用模型标无害性」推广成一条可测量的替代：在标准的摘要、有用对话任务上，AI 标签能否直接替换人类比较，而不明显掉胜率。InstructGPT 的瓶颈是人看完整回答；CAI 的重点是原则与标注员保护。RLAIF 的重点是对照实验：同一策略初始化、同一 PPO 配方，比较标签分别来自人和来自现成 LLM，看最终策略在人类评测上谁赢。论文同时扫标签器规模、思维链、宪法式原则，以及要不要先蒸馏成奖励模型。本篇写这条对照，而不是再推导一遍 PPO。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RLHF 的比较数据随提示多样性线性涨。摘要、对话的「哪条更好」需要读两段长文本，人标又慢又贵，还受标注员间一致性上限约束。若用一个已经对齐过的大模型当标签器，理论上可以并行打几百万对，但会引入三重误差：标签器与人类的不一致、提示措辞造成的标签噪声、以及用噪声 RM 做 PPO 时的过度优化。需要测量的不是「AI 能不能打标签」，而是这条误差链走到策略之后，人类还认不认。</p><p>Lee 等人选定两个有公开人类偏好的任务：Reddit TL;DR 摘要，以及 Anthropic HH 里的有用对话。这样可以同时报「AI 标签与人类标签的一致率」和「RLAIF 策略 vs RLHF 策略的人类胜率」。只有一致率没有策略胜率，会停在模仿标注员；只有策略胜率没有一致率，无法诊断是标签质量好还是 PPO 碰巧。</p><h3 id="标签器提示是实验的一等变量" tabindex="-1">标签器提示是实验的一等变量 <a class="header-anchor" href="#标签器提示是实验的一等变量" aria-label="Permalink to &quot;标签器提示是实验的一等变量&quot;">​</a></h3><p>直接问「A 和 B 谁好」会得到不稳定、偏长度、偏表面礼貌的标签。论文给标签器写详细准则，并试验先思维链再给选择，以及把宪法式原则写进提示。这与 CAI 同构，但任务从无害性扩到「摘要是否忠实、对话是否有用」。原则文本一旦写偏，AI 标签会系统性偏离人类——例如过度惩罚压缩、过度奖励罗列。扫提示与扫模型规模，在这篇论文里比扫 PPO 学习率更重要。</p><p><span class="marginnote">RLAIF 的「AI」指现成的、通常比策略更强或至少同级的指令模型，不是策略自己给自己打分。自我打分会把当前策略的盲区写成奖励。原文用独立的 PaLM 2 一类模型当标签器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>主路径与 RLHF 平行。用标签器对 \\((x,y_a,y_b)\\) 产生软或硬偏好，按 BT 训奖励模型 \\(r_\\phi\\)，再 PPO，KL 拴在 SFT。差别只在比较的来源。论文还试验 Direct-RLAIF：不训独立 RM，而在 PPO 时当场查询标签器，用其偏好概率或「好/坏」对数概率当奖励。当场查询更贵，省掉 RM 错指定的一层，但把标签器变成训练环里的服务，延迟和稳定性都更差。蒸馏路径（AI 对 → RM → PPO）是更可部署的默认。</p><p>评测用人类（或更强裁判）在持有提示上看 RLAIF 策略对 RLHF 策略、对 SFT 的胜率。同时报标签器-人类一致率随标签器规模、是否 CoT 的变化。主张是：在这两个任务上，RLAIF 可以达到与 RLHF 相近的人类胜率；更大的标签器和更好的提示会提高一致率，从而抬高最终策略。成本账按 token 计，相对人时低一个数量级以上——具体倍数随当时的 API 与薪酬变，论文给的是量级，不是可写入预算表的常数。</p>',12)),(e(),n(P,null,{default:r(()=>[s(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SFT%5B%22SFT%20%E7%AD%96%E7%95%A5%22%5D%20--%3E%20PAIR%5B%22%E9%87%87%E6%A0%B7%E6%88%90%E5%AF%B9%E5%AE%8C%E6%88%90%22%5D%0A%20%20PAIR%20--%3E%20HUM%5B%22%E4%BA%BA%E7%B1%BB%E6%AF%94%E8%BE%83%22%5D%0A%20%20PAIR%20--%3E%20AI%5B%22LLM%20%E6%8C%89%E5%8E%9F%E5%88%99%E6%AF%94%E8%BE%83%22%5D%0A%20%20HUM%20--%3E%20RMH%5B%22RM_HF%22%5D%0A%20%20AI%20--%3E%20RMA%5B%22RM_AIF%22%5D%0A%20%20RMH%20--%3E%20PPOH%5B%22PPO%20%E2%86%92%20RLHF%20%E7%AD%96%E7%95%A5%22%5D%0A%20%20RMA%20--%3E%20PPOA%5B%22PPO%20%E2%86%92%20RLAIF%20%E7%AD%96%E7%95%A5%22%5D%0A%20%20SFT%20--%3E%20PPOH%0A%20%20SFT%20--%3E%20PPOA%0A%20%20PPOA%20--%3E%20EV%5B%22%E4%BA%BA%E7%B1%BB%E8%83%9C%E7%8E%87%E5%AF%B9%E7%85%A7%22%5D%0A%20%20PPOH%20--%3E%20EV%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[R(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="一致率不是胜率的充分统计" tabindex="-1">一致率不是胜率的充分统计 <a class="header-anchor" href="#一致率不是胜率的充分统计" aria-label="Permalink to &quot;一致率不是胜率的充分统计&quot;">​</a></h3><p>标签器与人类 80% 一致，看起来很高，但仍有 20% 系统性错误。若错误集中在某一捷径（长度、第一人称道歉、格式符号），PPO 会把它放大成奖励黑客。论文因此必须看策略侧人类评测，而不能在一致率达标后停笔。Direct-RLAIF 若用标签器的链式推理当奖励，还可能把「会写评语」当成「完成更好」，策略学会在回答里夹带自我评价。奖励定义必须落在完成本身，而不是落在标签器的思维链上。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>AI 标签是有噪声的 BT 观测。噪声来自提示、位置偏差（A 在前更好）、长度偏差、以及标签器自己的对齐印迹——它可能比人类更拒答、更啰嗦、更像助手腔。RM 拟合这些观测，PPO 再拟合 RM。若噪声零均值且可被 \\(\\beta\\) 和 KL 限制，最终策略可以仍与 RLHF 接近；若噪声有偏，两条策略会沿不同方向离开 SFT。论文观察到在摘要、有用对话上偏差尚可管理，并不自动推广到无害性红队——无害性上 CAI 已经表明原则必须写得很显式，否则模型会表面合规。</p><p>规模机制是：更大的标签器更会执行复杂准则，CoT 把准则用到具体跨度上（哪一句不忠实），一致率上升。这与「用更大策略做 RL」不是同一笔计算。RLAIF 允许标签器 ≳ 策略，等于把一部分对齐计算花在离线打标上，策略可以更小——和 InstructGPT 用 6B RM 打 175B 策略的方向相反。两种分层都在承认：打分器与生成器不必同规模。</p><p><span class="marginnote">把 RLAIF 写成「CAI 的别名」不准确。CAI 的宪法针对伤害，并包含自我修订的监督阶段。RLAIF 论文的主对照是：通用偏好任务上 AI 比较能否顶替人。技术上可以共用原则提示，产品目标不同。</span></p><h3 id="蒸馏-rm-会再丢一层信息" tabindex="-1">蒸馏 RM 会再丢一层信息 <a class="header-anchor" href="#蒸馏-rm-会再丢一层信息" aria-label="Permalink to &quot;蒸馏 RM 会再丢一层信息&quot;">​</a></h3><p>标签器可能给出软概率或长篇理由。压成二元胜负再训 RM，丢掉理由，也丢掉不确定度。RM 容量若小于标签器，还会拟合不足。PPO 看到的奖励比原始 AI 判断更平滑，有时更稳，有时把标签器真正在意的细微差别抹掉。Direct-RLAIF 保留细微差别，但把训练稳定性交给现场查询。原文把两条都做了，工程上多数复现走蒸馏 RM。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>RLAIF 依赖标签器已经比策略更懂任务规范。用弱标签器给强策略打标，是在教策略模仿一个更差的裁判。标签器若与评测裁判同族，人类胜率会被高估。跨语言、工具调用、带私有知识的企业任务上，现成 LLM 可能系统性乱标，这时人标或专家标不能省。位置偏差要用随机交换 A/B 来减；不交换就会训出一个「总喜欢第一段」的 RM。</p><p>无害性、越狱、医疗法律，不能因为摘要任务上 RLAIF≈RLHF 就自动换标签源。CAI 把这类任务单独拆出，是因为错误标签的代价不对称。RLAIF 也没有取消 SFT：没有示范，采样对不在可排序区域，标签器会在两堆胡话里做选择。与 DPO 的关系：AI 比较一样可以进 DPO，不必 PPO；Lee 等人的主线仍是 RM+RL，因为他们要与经典 RLHF 做替换对照。</p><p><span class="marginnote">成本优势假设标签器推理比人时便宜。当策略规模追上标签器、每步 PPO 都要现场查询时，Direct-RLAIF 的账单会重新接近「用更大模型做生成」。应把打标算在数据预算里，而不是当成免费监督。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RLAIF 用独立 LLM 按准则生成成对偏好，再走 RM+PPO，与 RLHF 做同任务对照。</li><li>在 TL;DR 摘要与有用对话上，论文报告与人类反馈相近的最终人类胜率。</li><li>标签器规模、CoT、原则提示决定一致率；一致率不足以单独宣布成功。</li><li>蒸馏 RM 可部署；Direct-RLAIF 当场查询标签器，更贵、更贴原始判断。</li><li>标签器应强于策略且与评测裁判解耦；位置偏差要交换消除。</li><li>不替代 SFT，也不自动覆盖无害性红队；与 CAI 共用「AI 比较」，任务范围不同。</li><li>出处：Lee et al., <em>RLAIF vs. RLHF: Scaling Reinforcement Learning from Human Feedback with AI Feedback</em>, 2023。</li></ul>',14))])}const _=A(L,[["render",I]]);export{m as __pageData,_ as default};
